import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2020-07-16","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-07-16","date":"2020-07-16T00:00:00.000Z","updated":"2020-07-17T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","自动压缩"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-07-16.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-07-16.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Performance_Meeting_2020-07-16.md"};function r(n,e,s,h,c,d){return l(),i("div",null,[...e[0]||(e[0]=[t('<p>会议纪要</p><h2 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h2><ul><li><strong>日期与时间</strong>: 2020年7月16日，早晨开始。</li><li><strong>参会人员</strong>: Josh、Matt、Igor、Radik等Ceph研发人员和内容审核专家。</li></ul><h2 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h2><ol><li><p><strong>PR合并情况</strong>:</p><ul><li>讨论了多个PR的合并，包括性能测试、Jenkins失败原因、以及一些具体技术实现细节。</li><li>提到了PR在Octopus版本的回溯问题。</li></ul></li><li><p><strong>性能优化</strong>:</p><ul><li>讨论了MDS日志记录性能问题，特别是活跃的MDS配置下的日志记录代码开销。</li><li>探讨了使用Denk编码框架的可能性及其潜在问题。</li></ul></li><li><p><strong>RocksDB性能问题</strong>:</p><ul><li>Igor分享了RocksDB在大量删除操作后的性能问题，特别是在高负载下的表现。</li><li>讨论了手动压缩作为临时解决方案的有效性，以及自动压缩的潜在需求。</li></ul></li></ol><h2 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h2><ul><li>需要进一步研究和实验以确定Denk编码框架的可行性和性能提升。</li><li>对于RocksDB的性能问题，需要一个可靠的复现案例来进行深入分析和解决方案的开发。</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>继续研究和实验Denk编码框架，Radik将探索使用循环缓冲区来优化内存分配。</li><li>寻找和建立RocksDB性能问题的可靠复现案例，以便进行针对性的优化。</li><li>考虑实施自动压缩机制，减轻手动压缩的负担。</li></ul><h2 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h2><ul><li>会议中提到了多个具体的PR和代码变更，这些细节对于后续的技术实现和问题解决具有重要参考价值。</li><li>强调了团队合作和持续改进的重要性，特别是在面对复杂的技术挑战时。</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>会议对当前的技术挑战进行了深入讨论，并制定了具体的后续行动计划。团队将继续致力于性能优化和问题解决，以提升Ceph存储系统的稳定性和效率。</p>',13)])])}const _=a(o,[["render",r]]);export{u as __pageData,_ as default};
